fn solve(n: usize, s: Vec<char>) -> Vec<char> {
    // Count of transitions from 'S' to 'F'
    let mut count_sf = 0;
    // Count of transitions from 'F' to 'S'
    let mut count_fs = 0;

    // Iterate over all adjacent pairs
    for i in 1..n {
        if s[i - 1] == 'S' && s[i] == 'F' {
            count_sf += 1;
        } else if s[i - 1] == 'F' && s[i] == 'S' {
            count_fs += 1;
        }
    }

    // If SF transitions strictly exceed FS transitions, return "YES"
    if count_sf > count_fs {
        vec!['Y', 'E', 'S']
    } else {
        vec!['N', 'O']
    }
}